export function tools({ tools: t }) {
  return [
    { type: 'stats', items: [{ label: 'tool calls', value: t.total.calls }, { label: 'turns', value: t.total.turns }, { label: 'spend', value: Math.round(t.total.cost * 100) / 100, unit: '$' }] },
    { type: 'chart', title: 'By kind', items: t.kinds.map((k) => ({ label: k.kind, value: k.calls })) },
    { type: 'chart', title: 'By harness', items: t.agents.map((a) => ({ label: a.agent, value: a.calls })) },
  ];
}

export function deploy(b) {
  return [
    { type: 'callout', tone: b.status === 'ok' ? 'success' : 'danger', title: `${b.env} · ${b.status}`, text: b.url },
    { type: 'checklist', items: (b.checks || []).map((c) => ({ text: c.label, done: !!c.ok })) },
  ];
}

export function rank(b) {
  const items = (b.items || []).map(String);
  const css = '<style>ol{margin:0;padding:12px 14px 8px;list-style:none;display:flex;flex-direction:column;gap:6px}li{display:flex;align-items:center;gap:8px;padding:8px 10px;border:1px solid var(--line);border-radius:8px}li span{flex:1;min-width:0}li button{border:1px solid var(--line-2);border-radius:6px;background:var(--surface);cursor:pointer}.go{margin:4px 14px 14px;padding:7px 12px;border:0;border-radius:8px;background:var(--accent);color:#fff;cursor:pointer}</style>';
  const js = "let o=wisp.state||" + JSON.stringify(items).replace(/</g, '\\u003c') + ";const l=document.getElementById('l');" +
    "const draw=()=>{l.innerHTML=o.map((t,i)=>'<li><span></span>'+(i?'<button data-i=\"'+i+'\">Up</button>':'')+'</li>').join('');l.querySelectorAll('span').forEach((s,i)=>{s.textContent=(i+1)+'. '+o[i]});wisp.save(o)};" +
    "l.onclick=(e)=>{const i=+e.target.dataset.i;if(i){[o[i-1],o[i]]=[o[i],o[i-1]];draw()}};" +
    "document.getElementById('go').onclick=()=>{wisp.send('My order:\\n'+o.map((t,i)=>(i+1)+'. '+t).join('\\n'))};draw();";
  const html = css + '<ol id="l"></ol><button class="go" id="go">Send this order</button><script>' + js + '</scr' + 'ipt>';
  return [{ type: 'app', title: b.title || 'Rank these', html, fallback: [{ type: 'checklist', items: items.map((t) => ({ text: t })) }] }];
}

